export const BRAND='Biottos Lädeli';
export const EMAIL='biottoslaedeli@gmail.com';
export const PHONE='+41523653658';
export const PHONE_DISPLAY='052 365 36 58';
export const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const json=value=>JSON.stringify(value).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026');
export function money(value){return `CHF ${Number(value.amount).toLocaleString('de-CH',{minimumFractionDigits:2,maximumFractionDigits:2})}`;}
export function icon(name){const paths={cart:'<path d="M2 3h3l3 13h11l3-10H6"/><circle cx="9" cy="21" r="1"/><circle cx="19" cy="21" r="1"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/>',gift:'<path d="M3 10h18v4H3zM5 14v8h14v-8M12 10v12"/><path d="M12 10C0 10 5-2 12 10c7-12 12 0 0 0Z"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="1"/><path d="m2 5 10 8 10-8"/>',leaf:'<path d="M4 20C-2 6 10 3 22 2c0 14-7 22-18 18ZM4 20 18 6"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',arrow:'<path d="M3 12h18m-7-7 7 7-7 7"/>',chevron:'<path d="m5 9 7 7 7-7"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[name]||''}</svg>`;}
export function image(img, {className='',loading='lazy',width=900,sizes='(min-width: 1100px) 23vw, (min-width: 600px) 45vw, 90vw',title=''}={}) {
 if(!img)return '<div class="missing-image">Produktbild folgt</div>';
 const url=new URL(img.url);if(url.protocol!=='https:')return '<div class="missing-image">Produktbild folgt</div>';
 const source=w=>{const next=new URL(url);next.searchParams.set('width',w);return escape(next.href);};
 const suppliedAlt=typeof img.altText==='string'?img.altText.trim():'';
 const descriptiveAlt=/^(?:rn[-_])?image[-_]?picker[-_]?lib[-_]?temp/i.test(suppliedAlt)?title:(suppliedAlt||title);
 return `<img src="${source(width)}" srcset="${[320,600,900,1200].map(w=>`${source(w)} ${w}w`).join(', ')}" sizes="${escape(sizes)}" width="${Number(img.width)||900}" height="${Number(img.height)||900}" loading="${loading}" decoding="async" class="${escape(className)}" alt="${escape(descriptiveAlt)}">`;
}
export const productUrl=p=>`/produkte/${encodeURIComponent(p.handle)}`;
export function lowestPrice(p){return p.variants.reduce((a,v)=>Number(v.price.amount)<Number(a.price.amount)?v:a,p.variants[0]).price;}
const subtitles={'chli-fii':'3 Fläschchen à 250 ml','fein-guet':'5 Spezialitäten','gross-guet':'7 Spezialitäten'};
const vinegarLineupItems=[
 ['Birnenessig','essig-birnen','birnenessig'],
 ['Holunderblütenessig','essig-holunder','holunderblutenessig'],
 ['Birnen-Balsamico','essig-balsamico','birnen-balsamico'],
 ['Apfelessig · 33 Sorten','essig-original','apfelessig-33-sorten'],
 ['Kirschessig','essig-kirsch','kirschessig'],
 ['Himbeeressig','essig-himbeer','himbeeressig'],
 ['Kirschen-Birnen-Essig','essig-kirschen-birnen','kirschen-birnen-essig']
];
function vinegarLineup(products){
 const catalog=new Map(products.map(product=>[product.handle,product]));
 return `<div class="vinegar-lineup" aria-label="Sieben Essig- und Balsamicosorten">${vinegarLineupItems.map(([label,asset,handle])=>{
  const product=catalog.get(handle);
  const href=product?productUrl(product):`/sortiment?kategorie=${encodeURIComponent('Essig & Balsamico')}`;
  return `<figure class="vinegar-lineup-item"><a class="vinegar-bottle-trigger" data-vinegar-bottle href="${escape(href)}" aria-label="${escape(label)} ansehen und kaufen"><img data-src="/assets/${asset}-cutout.svg?v=mosti-cutout-3" width="960" height="960" alt="${escape(label)} – Originalflasche und Originaletikett" loading="lazy" decoding="async"></a><figcaption>${escape(label)}</figcaption></figure>`;
 }).join('')}</div>`;
}
export function buyForm(product,{detail=false,idSuffix='',buttonText='In den Warenkorb'}={}) {
 const selected=product.variants.find(v=>v.availableForSale)||product.variants[0];
 const variants=product.variants.length>1;
 return `<form class="product-form" data-product="${escape(product.id)}" action="/api/cart/add" method="post">
 ${variants?`<label class="variant-label" for="Variant-${escape(product.handle)}${detail?'-detail':''}${escape(idSuffix)}">Gebinde / Variante</label><select name="variantId" id="Variant-${escape(product.handle)}${detail?'-detail':''}${escape(idSuffix)}" data-variant-select>${product.variants.map(v=>`<option value="${escape(v.id)}" data-title="${escape(v.title)}" data-available="${v.availableForSale}" data-alt="${escape(v.image?.altText||`${product.title} · ${v.title}`)}" data-price="${escape(money(v.price))}" data-image="${escape(v.image?.url||product.featuredImage?.url||'')}" ${v.id===selected.id?'selected':''} ${v.availableForSale?'':'disabled'}>${escape(v.title)} · ${money(v.price)}${v.availableForSale?'':' · Ausverkauft'}</option>`).join('')}</select>`:`<input name="variantId" type="hidden" value="${escape(selected.id)}">`}
 ${detail?'<label for="ProductQuantity">Menge</label><input id="ProductQuantity" name="quantity" type="number" value="1" min="1" max="250" step="1" required>':'<input type="hidden" name="quantity" value="1">'}
 <button class="button" type="submit" ${product.availableForSale&&selected.availableForSale?'':'disabled'}>${icon('cart')}${product.availableForSale?escape(buttonText):'Ausverkauft'}</button><p class="form-error" role="alert" hidden></p></form>`;
}
export function card(product,{featured=false}={}) {return `<article class="product-card" data-card="${escape(product.handle)}"><a class="product-image ${featured?'':'catalog-image'}" href="${productUrl(product)}">${image(product.featuredImage,{title:product.title})}</a><div class="card-body"><h2><a href="${productUrl(product)}">${escape(product.title)}</a></h2>${featured&&subtitles[product.handle]?`<p>${subtitles[product.handle]}</p>`:''}<p class="price" data-price>${product.variants.length>1?'Ab ':''}${money(lowestPrice(product))}</p>${buyForm(product)}</div></article>`;}
function nav(path){return `<ul class="nav-list"><li><a href="/" ${path==='/'?'aria-current="page"':''}>Startseite</a></li><li><details class="nav-dropdown" ${path==='/saisonales'?'open':''}><summary>Sortiment ${icon('chevron')}</summary><ul class="dropdown"><li><a href="/sortiment" ${path==='/sortiment'?'aria-current="page"':''}>Alle Produkte</a></li><li><a href="/saisonales" ${path==='/saisonales'?'aria-current="page"':''}>Saisonales</a></li><li><a href="/sortiment?kategorie=${encodeURIComponent('Säfte')}">Säfte</a></li><li><a href="/sortiment?kategorie=${encodeURIComponent('Essig & Balsamico')}">Essig & Balsamico</a></li><li><a href="/sortiment?kategorie=${encodeURIComponent('Spezialitäten')}">Spezialitäten</a></li><li><a href="/sortiment?kategorie=${encodeURIComponent('Dörrfrüchte')}">Dörrfrüchte</a></li><li><a href="/sortiment?kategorie=${encodeURIComponent('Backwaren')}">Backwaren</a></li></ul></details></li><li><a href="/kochservice" ${path==='/kochservice'?'aria-current="page"':''}>Kochservice</a></li><li><a href="/garten" ${path==='/garten'?'aria-current="page"':''}>Garten</a></li><li><a href="/geschenkkoerbe" ${path==='/geschenkkoerbe'?'aria-current="page"':''}>Geschenkkörbe</a></li><li><a href="/ueber-uns" ${path==='/ueber-uns'?'aria-current="page"':''}>Über uns</a></li><li><a href="/kontakt" ${path==='/kontakt'?'aria-current="page"':''}>Kontakt</a></li></ul>`;}
const pickupFaq=[
 {question:'Wo befindet sich Biottos Lädeli?',answer:'An der Hauptstrasse 90 in Maischhausen (Gemeinde Aadorf), Postort 8357 Guntershausen im Thurgau.'},
 {question:'Wann ist die Abholung möglich?',answer:'Montag bis Samstag von 08:00 bis 22:00 Uhr. Sonntag geschlossen.'},
 {question:'Ist Biottos Lädeli ein Selbstbedienungsladen?',answer:'Ja, du kannst vor Ort selbstständig einkaufen. Bei Fragen ist eine Ansprechperson telefonisch erreichbar.'},
 {question:'Sind individuelle Geschenke für Firmen möglich?',answer:'Ja. Für Firmengeschenke und persönliche Geschenkharasse kannst du uns über die Kontaktseite eine Anfrage senden.'}
];
